CREATE TABLE marketplace_installs(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,version text NOT NULL,kind text NOT NULL,description text NOT NULL DEFAULT '',content_digest text NOT NULL,publisher_name text NOT NULL,publisher_key_id text NOT NULL,trust_level text NOT NULL CHECK(trust_level IN('verified','community','experimental')),capabilities jsonb NOT NULL DEFAULT '{}',sandbox_only boolean NOT NULL DEFAULT true,installed_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,id),UNIQUE(owner_id,name));
CREATE INDEX marketplace_installs_owner ON marketplace_installs(owner_id,installed_at,id);
